import { createRouter } from '@tanstack/react-router';
import { routeTree } from '~/routeTree.gen';

/**
 * File-based routing: every file under `src/routes` is a route, and
 * `routeTree.gen.ts` is regenerated by the Vite plugin. Do not edit it.
 *
 * Conventions:
 *   routes/__root.tsx        the application shell — toolbar, sidebar, status bar
 *   routes/index.tsx         `/`               board picker
 *   routes/boards.$boardId   `/boards/:boardId` the canvas
 *   routes/library.tsx       `/library`        the reference library
 *   routes/settings.tsx      `/settings`
 *   routes/instance.tsx      `/instance`       Instance Settings (staff)
 */
export const router = createRouter({
  routeTree,
  defaultPreload: 'intent',
  scrollRestoration: false,
});

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}
